def decode_bg(blob, palette):
    """RLE+base64 blob -> (142,160,3) uint8 image."""
    raw = base64.b64decode(blob)
    flat = np.zeros(142 * 160, np.uint8)
    pos = 0
    for i in range(0, len(raw), 2):
        v, ln = raw[i], raw[i + 1]
        flat[pos:pos + ln] = v
        pos += ln
    idx = flat.reshape(142, 160)
    return np.array(palette, np.uint8)[idx]


# ---------------------------------------------------------------------------
# Authored object data (measured from the same ROM captures).
# All coordinates are SCREEN pixels within a room's 142x160 cave view.
# ---------------------------------------------------------------------------
# The game has 20 distinct levels and reuses them afterwards (HERO_SPEC.md
# section 8). Both numbers are the ROM's, and the tests re-check them against
# tests/games/hero_rooms_ref.py so they cannot drift.
NUM_LEVELS = 20
ROOMS_PER_LEVEL = [2, 4, 6, 8, 8, 10, 12, 14, 16, 16,
                   16, 16, 16, 16, 16, 16, 16, 16, 16, 16]
assert len(ROOMS_PER_LEVEL) == NUM_LEVELS

# The cave hue cycles brown / green / blue / grey, and each hue is a seven
# step ramp: `edge` is the seam between bands, `dark`/`mid`/`light` are the
# ceiling / corridor / floor bodies, and hi1-hi3 the wavy trim on rows 16-19
# and 138-141. Read out of the ROM's colour registers (RAM 69/70/71).
#
# Green's dark / mid / light are the three the reference pack got wrong. It
# lists #1a641a / #2f832f / #479f47; the ROM paints #1a661a / #328432 /
# #48a048, measured off the level 2 capture (rooms 1-3, 5,304 pixels of each
# in its own band) and already in PALETTE_L6 / L10 / L14 from the earlier
# capture of those green levels. tools/hero_gen/build_level.py now refuses to
# emit a level whose shades the ROM does not paint, so this cannot drift back.
SHADES = {
    lv: dict(zip(("edge", "dark", "mid", "light", "hi1", "hi2", "hi3"), ramp))
    for lv, ramp in (
        (n, {"brown": ("#7c2c00", "#904811", "#a26221", "#b47a30",
                       "#c3903d", "#d2a44a", "#dfb755"),
             "green": ("#004400", "#1a661a", "#328432", "#48a048",
                       "#5cba5c", "#6fd26f", "#80e880"),
             "blue":  ("#001c88", "#183b9d", "#2d57b0", "#4272c2",
                       "#548ad2", "#65a0e1", "#75b5ef"),
             "grey":  ("#2a2a2a", "#4a4a4a", "#6f6f6f", "#8e8e8e",
                       "#aaaaaa", "#c0c0c0", "#d6d6d6")}[
            ("brown", "green", "blue", "grey")[(n - 1) % 4]])
        for n in range(1, NUM_LEVELS + 1))
}

