# Physical walls drawn on two screens at once. The ROM keeps one copy of each
# distinct band pattern, so two bands that look identical ARE the same memory:
# blasting the column out of one clears it from the other.
#
# The level-1 evidence this rule used to cite was an artefact and is gone.
# It ran: "blast the pillar at x 60-67 in room 0 and room 1's middle band
# loses it at the same instant". Room 1's middle band never had a pillar -
# the superseded capture had simply copied room 0's corridor into it. The
# real level 1 is
#
#   room 0  B ##...........##...................####    <- the one pillar
#   room 1  B ####............................######    <- open end to end
#
# so a clean level-1 clear still scores 75 for one wall, but because there
# is one wall, not because two share a column. Level 1's group list is now
# empty, and so is level 2's for the same reason - all four of its rooms draw
# a different corridor. The groups for levels 3-16 were worked out on the same
# superseded capture and have to be re-derived when each of those levels is
# rebuilt.
#
# Each entry of a level's list is a group of DESTRUCTIBLE slot indices that
# are one wall: breaking any of them breaks all of them, and the group scores
# 75 once. Levels with no grouping keep one slot per wall.
SHARED_WALLS = [
    [],
    [],
    [],
    [],
    [],
    [],
    [],
    [],
    [],
    [],
    [],
    [],
    [],
    [],
    [],
    [],
    [],
    [],
]


