# ---------------------------------------------------------------------------
# Levels 19-20: PLACEHOLDERS, not measured.
#
# NUM_LEVELS is 20 because the ROM has 20 distinct levels, but only levels
# 1-18 have been captured into this module so far. Until the per-level ROM
# pass reaches them, levels 19-20 alias levels 15-16 — which at least puts
# them in the right hue family, since the cave hue cycles brown/green/blue/
# grey and 13/17 are brown, 14/18 green, 15/19 blue, 16/20 grey — and gives
# them the right room count (16 each, per ROOMS_PER_LEVEL).
# Everything here is a stand-in: replace it with measured data, do not build
# on it.
# ---------------------------------------------------------------------------
_PLACEHOLDER_SRC = (15, 16)                  # level 19 <- 15, 20 <- 16

PALETTE_L19, PALETTE_L20 = (
    PALETTE_L15, PALETTE_L16)
BG_RLE_L19, BG_RLE_L20 = (
    BG_RLE_L15, BG_RLE_L16)
WALL_RECTS_L19, WALL_RECTS_L20 = (
    WALL_RECTS_L15, WALL_RECTS_L16)

for _lst in (MINER_POS, SPIDERS, LANTERNS, DESTRUCTIBLE, DEADLY, FLARES, RAFTS,
             SHARED_WALLS, MAGMA, MAGMA_MOUTHS):
    assert len(_lst) == 18, "expected the 18 measured levels before padding"
    _lst.extend(list(_lst[_src - 1]) if isinstance(_lst[_src - 1], list)
                else _lst[_src - 1] for _src in _PLACEHOLDER_SRC)
    assert len(_lst) == NUM_LEVELS
del _lst

# Every level index 0..NUM_LEVELS-1 must now resolve.
assert all(f"PALETTE_L{_i}" in globals() and f"BG_RLE_L{_i}" in globals()
           and f"WALL_RECTS_L{_i}" in globals()
           for _i in range(1, NUM_LEVELS + 1))
